using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.Messages;
namespace TechnifyERP.Areas.Student.Controllers;
[Area("Student"),Authorize(Roles="Student")]public sealed class MessagesController(IMessageService service):Controller
{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Contacts=(await service.GetContactsAsync(Id,"Student",ct)).Select(x=>new SelectListItem($"{x.FullName} ({x.Role})",x.UserId));ViewBag.Sent=await service.GetSentAsync(Id,ct);return View(await service.GetInboxAsync(Id,ct));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Send(string recipientId,string subject,string body,CancellationToken ct){await service.SendAsync(Id,"Student",recipientId,subject,body,ct);return RedirectToAction(nameof(Index));}public async Task<IActionResult>Read(int id,CancellationToken ct){var m=await service.GetAsync(Id,id,ct);return m is null?NotFound():View(m);}private string Id=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;}
